-- Run on the separate CINENTO SITE Supabase project after reviewing the target project.
-- This migration has no reference to the older CINENTO database.
create table if not exists public.site_programs (
  id text primary key check (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name text not null check (length(name) between 1 and 120),
  mark text not null check (length(mark) between 1 and 24),
  category text not null check (category in ('intelligence','media','business','connectivity')),
  status text check (status in ('desktop','development')),
  copy jsonb not null,
  access_url text,
  published boolean not null default false,
  sort_order integer not null default 100 check (sort_order between 0 and 9999),
  updated_at timestamptz not null default now()
);
create table if not exists public.site_catalog_admins (
  user_id uuid primary key references auth.users(id) on delete cascade
);
alter table public.site_programs enable row level security;
alter table public.site_catalog_admins enable row level security;
revoke all on public.site_programs from public, anon, authenticated;
revoke all on public.site_catalog_admins from public, anon, authenticated;
grant select on public.site_programs to anon;
grant select, insert, update, delete on public.site_programs to authenticated;
grant select on public.site_catalog_admins to authenticated;
create policy site_catalog_admin_self on public.site_catalog_admins for select to authenticated
  using (user_id = (select auth.uid()));
create policy site_programs_public_read on public.site_programs for select to anon, authenticated
  using (published = true);
create policy site_programs_admin_read on public.site_programs for select to authenticated
  using (exists (select 1 from public.site_catalog_admins where user_id = (select auth.uid())));
create policy site_programs_admin_insert on public.site_programs for insert to authenticated
  with check (exists (select 1 from public.site_catalog_admins where user_id = (select auth.uid())));
create policy site_programs_admin_update on public.site_programs for update to authenticated
  using (exists (select 1 from public.site_catalog_admins where user_id = (select auth.uid())))
  with check (exists (select 1 from public.site_catalog_admins where user_id = (select auth.uid())));
create policy site_programs_admin_delete on public.site_programs for delete to authenticated
  using (exists (select 1 from public.site_catalog_admins where user_id = (select auth.uid())));
-- Idempotent initial import: existing owner edits are never overwritten.
insert into public.site_programs (id,name,mark,category,status,copy,access_url,published,sort_order) values
  ('ai','CINENTO AI','AI','intelligence',NULL,'{"en":{"description":"An AI assistant workspace designed for film ideas, content, marketing, professional writing and document analysis. Access requires an account.","audience":"Creators, professionals and teams","scope":["Film ideas and project outlines","Marketing content","Letters and reports","Document summaries"],"service":"AI experience design"},"tr":{"description":"Film fikirleri, içerik, pazarlama, profesyonel yazım ve belge analizi için tasarlanan yapay zekâ asistanı çalışma alanı. Erişim için hesap gerekir.","audience":"Yaratıcılar, profesyoneller ve ekipler","scope":["Film fikirleri ve proje taslakları","Pazarlama içeriği","Yazışmalar ve raporlar","Belge özetleri"],"service":"Yapay zekâ deneyimi tasarımı"},"fa":{"description":"محیط دستیار هوش مصنوعی، طراحی‌شده برای ایده‌های فیلم، محتوا، بازاریابی، نگارش حرفه‌ای و تحلیل اسناد. دسترسی نیازمند حساب کاربری است.","audience":"تولیدکنندگان محتوا، متخصصان و تیم‌ها","scope":["ایده فیلم و طرح پروژه","محتوای بازاریابی","نامه‌ها و گزارش‌ها","خلاصه اسناد"],"service":"طراحی تجربه هوش مصنوعی"}}'::jsonb,'https://ai.cinento.net',true,0),
  ('watch','CINENTO WATCH','W','media',NULL,'{"en":{"description":"CINENTO’s independent cinematic platform for discovering and watching selected titles. An early release with a limited catalog, evolving for audiences, filmmakers and media partners.","audience":"Audiences, filmmakers and media partners","scope":["Selected title catalog","Title information","Video playback"],"service":"Film and media strategy"},"tr":{"description":"Seçili yapımları keşfetmek ve izlemek için CINENTO’nun bağımsız sinema platformu. İzleyiciler, sinemacılar ve medya ortakları için geliştirilen, sınırlı kataloglu ilk sürüm.","audience":"İzleyiciler, sinemacılar ve medya ortakları","scope":["Seçili yapım kataloğu","Yapım bilgileri","Video oynatma"],"service":"Sinema ve medya stratejisi"},"fa":{"description":"پلتفرم مستقل سینمایی CINENTO برای کشف و تماشای آثار منتخب؛ نسخه‌ای اولیه با فهرست محدود که برای مخاطبان، فیلم‌سازان و شرکای رسانه‌ای توسعه می‌یابد.","audience":"مخاطبان، فیلم‌سازان و شرکای رسانه‌ای","scope":["فهرست آثار منتخب","اطلاعات آثار","پخش ویدئو"],"service":"راهبرد سینما و رسانه"}}'::jsonb,'https://watch.cinento.net',true,1),
